async function withBusy(buttons, fn) {
const list = (Array.isArray(buttons) ? buttons : [buttons]).filter(Boolean);
const prev = list.map((b) => !!b.disabled);
list.forEach((b) => {
b.disabled = true;
b.classList.add("is-busy");
});
try {
return await fn();
} finally {
list.forEach((b, i) => {
b.disabled = prev[i];
b.classList.remove("is-busy");
});
}
}
