function initials(name) {
const s = String(name || "TG").trim();
if (!s) return "TG";
if (/[\u3400-\u9fff]/.test(s[0])) return s[0];
const parts = s.replace(/^@/, "").split(/\s+/).filter(Boolean);
if (parts.length >= 2) {
return (parts[0][0] + parts[1][0]).toUpperCase();
}
return s.slice(0, 2).toUpperCase();
}
