async function verifyWebSession() {
return Promise.race([
api("/api/auth/web-session"),
new Promise((_, reject) =>
setTimeout(() => reject(new Error("会话检查超时")), 2500)
),
]);
}
async function bootstrap() {
bindUi();
bindIosHairlineGuards();
const hinted = hasWebAuthedHint();
if (hinted) {
enterApp({ background: true, soft: true });
verifyWebSession()
.then((web) => {
if (web && (web.authenticated || !web.need_password)) {
state.webUsername = web.username || state.webUsername;
applyAccountChip();
markWebAuthedHint();
return;
}
if (web && web.need_password && web.authenticated === false) {
clearWebAuthedHint();
showWebLogin();
}
})
.catch(() => {
});
return;
}
try {
const web = await verifyWebSession();
if (!web.need_password || web.authenticated) {
state.webUsername = web.username || null;
applyAccountChip();
markWebAuthedHint();
enterApp({ background: true, soft: false });
return;
}
clearWebAuthedHint();
showWebLogin();
} catch (e) {
if (e && e.message && /超时/.test(e.message) && hasWebAuthedHint()) {
enterApp({ background: true, soft: true });
return;
}
if (e && e.message && !/超时/.test(e.message) && !isSoftAuthError(e)) {
setMsg($("webAuthMsg"), e.message || String(e), "err");
}
clearWebAuthedHint();
showWebLogin();
}
}
function enterApp(opts = {}) {
showApp();
state.page = "tasks";
const pageTasks = $("pageTasks");
const pageHistory = $("pageHistory");
if (pageTasks) pageTasks.hidden = false;
if (pageHistory) pageHistory.hidden = true;
$("btnNavTasks")?.classList.toggle("is-active", true);
$("btnNavHistory")?.classList.toggle("is-active", false);
startPolling();
if (opts.soft) {
restoreTaskListCache();
}
const boot = (async () => {
try {
await loadTasks({ force: true });
} catch (_) {}
await Promise.allSettled([
refreshTgState(),
loadTaskDefaults(),
loadTagBlacklist({ render: false }).catch(() => {}),
]);
})();
if (opts.background) {
boot.catch(() => {});
return boot;
}
return boot;
}
function isCoarseTouchUi() {
try {
return window.matchMedia("(hover: none) and (pointer: coarse)").matches
|| window.matchMedia("(max-width: 860px)").matches;
} catch (_) {
return false;
}
}
function fitMobileTaskLogToBottom() {
const touch =
document.documentElement.classList.contains("touch-ui") || isCoarseTouchUi();
if (!touch) return;
const page = $("pageTasks");
if (!page || page.hidden) return;
const tasks = document.querySelectorAll(".page-tasks .tasks > .task");
const clearFit = (log) => {
const body = log?.querySelector(".task-log-body, .task-log-empty");
if (!body) return;
body.style.height = "";
body.style.minHeight = "";
body.style.maxHeight = "";
log.style.maxHeight = "";
};
if (tasks.length !== 1) {
tasks.forEach((t) => clearFit(t.querySelector(".task-log")));
return;
}
const log = tasks[0].querySelector(".task-log");
const body = log?.querySelector(".task-log-body, .task-log-empty");
if (!body) return;
log.style.maxHeight = "none";
body.style.height = "";
body.style.minHeight = "";
body.style.maxHeight = "none";
void body.offsetHeight;
const rect = body.getBoundingClientRect();
const scrollY = window.scrollY || window.pageYOffset || 0;
const topDoc = rect.top + scrollY;
let safeBottom = 0;
try {
safeBottom =
parseFloat(
getComputedStyle(document.documentElement).getPropertyValue("--safe-bottom")
) || 0;
} catch (_) {}
const bottomPad = Math.max(10, safeBottom + 6);
const h = Math.max(200, Math.floor(window.innerHeight - topDoc - bottomPad));
body.style.height = `${h}px`;
body.style.minHeight = `${h}px`;
body.style.maxHeight = "none";
}
function scheduleFitMobileTaskLog() {
if (state._fitLogRaf) cancelAnimationFrame(state._fitLogRaf);
state._fitLogRaf = requestAnimationFrame(() => {
state._fitLogRaf = 0;
fitMobileTaskLogToBottom();
requestAnimationFrame(fitMobileTaskLogToBottom);
});
}
function nudgeIosRepaint(root) {
if (!isCoarseTouchUi() && !document.documentElement.classList.contains("touch-ui")) {
return;
}
const el = root || document.body;
if (!el) return;
el.classList.add("ios-repaint-nudge");
void el.offsetHeight;
requestAnimationFrame(() => {
el.classList.remove("ios-repaint-nudge");
});
}
function scheduleIosHairlinePass() {
if (!isCoarseTouchUi() && !document.documentElement.classList.contains("touch-ui")) {
return;
}
const delays = [0, 50, 150, 400, 900, 1800];
delays.forEach((ms) => {
setTimeout(() => nudgeIosRepaint(document.documentElement), ms);
});
try {
if (document.fonts && document.fonts.ready) {
document.fonts.ready.then(() => {
nudgeIosRepaint(document.documentElement);
setTimeout(() => nudgeIosRepaint(document.documentElement), 200);
});
}
} catch (_) {}
}
function bindIosHairlineGuards() {
if (!isCoarseTouchUi() && !document.documentElement.classList.contains("touch-ui")) {
return;
}
if (state._iosHairlineBound) return;
state._iosHairlineBound = true;
let t = 0;
const kick = () => {
clearTimeout(t);
t = setTimeout(() => nudgeIosRepaint(document.documentElement), 80);
};
document.addEventListener("visibilitychange", () => {
if (!document.hidden) {
kick();
scheduleIosHairlinePass();
}
});
window.addEventListener("pageshow", (ev) => {
kick();
if (ev.persisted) scheduleIosHairlinePass();
});
window.addEventListener("orientationchange", () => {
scheduleIosHairlinePass();
});
document.addEventListener(
"scroll",
(ev) => {
const tgt = ev.target;
if (!tgt || tgt === document || tgt === document.documentElement || tgt === document.body) {
kick();
return;
}
if (
tgt.classList?.contains("tasks") ||
tgt.classList?.contains("tasks-page-shell") ||
tgt.classList?.contains("history-list") ||
tgt.classList?.contains("task-log-body")
) {
kick();
}
},
{ passive: true, capture: true }
);
scheduleIosHairlinePass();
}
function switchPage(name) {
const page = name === "history" ? "history" : "tasks";
state.page = page;
const pageTasks = $("pageTasks");
const pageHistory = $("pageHistory");
if (pageTasks) pageTasks.hidden = page !== "tasks";
if (pageHistory) pageHistory.hidden = page !== "history";
$("btnNavTasks")?.classList.toggle("is-active", page === "tasks");
$("btnNavHistory")?.classList.toggle("is-active", page === "history");
if (page === "history") {
loadHistory(state.historyOffset || 0).catch((e) => {
if (!isSoftAuthError(e)) toast(e.message || String(e), "err");
});
} else {
loadTasks().catch(() => {});
}
requestAnimationFrame(() => {
nudgeIosRepaint(document.documentElement);
scheduleIosHairlinePass();
scheduleFitMobileTaskLog();
});
}
