function taskModeMeta(t) {
const mode = normalizeDownloadMode(t && t.download_mode);
if (mode === "monitor") {
return {
mode: "monitor",
label: "监控",
tip: "对比本地标签索引与已下载；索引手动/自动/全量更新后再补差集（不空转轮询）",
};
}
return {
mode: "sequential",
label: "时间顺序",
tip: "按群消息时间顺序依次下载",
};
}
function renderMonitorTagHint(t) {
if (!isMonitorTask(t) || taskHasMonitorTags(t)) return "";
return `<button type="button" class="task-monitor-hint" data-action="open-settings" data-id="${escapeHtml(String(t.id))}">
未选标签 · 等待配置 · 去设置添加标签后才会按差集下载
</button>`;
}
function renderTask(t) {
const status = t.status || "pending";
const statusClass = `status-${status}`;
const modeMeta = taskModeMeta(t);
const q = queueRemaining(t);
const title = t.chat_title || t.chat_id || "";
const startLabel = startActionLabel(t);
const startState = startActionState(t);
const startRunning = status === "running";
const mon = isMonitorTask(t);
const startDisabled = startRunning && !mon;
const startAction = mon && startRunning ? "pause" : "start";
const startTitle = mon
? startRunning
? "点击暂停监控"
: "点击开始/恢复监控"
: startRunning
? "下载进行中"
: "继续下载";
const startIco = startRunning
? mon
? "ui-ico-pause"
: "ui-ico-check"
: "ui-ico-play";
const statTitles = taskStatTitles(t);
return `<div class="task" data-task-id="${t.id}" data-status="${escapeHtml(status)}" data-mode="${modeMeta.mode}">
<div class="task-head">
<div class="task-head-main">
<div class="task-mode-row">
<span class="task-mode-badge" data-mode="${modeMeta.mode}" title="${escapeHtml(modeMeta.tip)}">${escapeHtml(modeMeta.label)}</span>
</div>
<p class="task-title" title="${escapeHtml(title)}">${escapeHtml(title)}</p>
</div>
<span class="status-pill ${statusClass}">${escapeHtml(statusLabel(t.status, t))}</span>
</div>
<div class="task-body">
<div class="task-stats" aria-label="任务进度">
${renderTaskStatsHtml(t, tagMatchDisplay(t), q, indexMediaDisplay(t), statTitles)}
</div>
${renderMonitorTagHint(t)}
<div class="task-actions" data-mode="${mon ? "monitor" : "sequential"}">
<button type="button" data-role="start-btn" data-action="${startAction}" data-id="${t.id}" data-monitor-state="${escapeHtml(startState)}" title="${escapeHtml(startTitle)}" ${startDisabled ? "disabled" : ""}>
<span class="ui-ico ${startIco}" aria-hidden="true"></span><span data-role="start-label">${escapeHtml(startLabel)}</span>
</button>
<button type="button" data-role="pause-btn" data-action="pause" data-id="${t.id}" class="${!mon && startRunning ? "is-pause-ready" : ""}" title="${startRunning ? "暂停任务" : "未在运行，无法暂停"}" ${mon ? "hidden disabled" : startRunning ? "" : "disabled"}>
<span class="ui-ico ui-ico-pause" aria-hidden="true"></span><span>暂停</span>
</button>
<button type="button" class="ghost" data-action="open-settings" data-id="${t.id}">
<span class="ui-ico ui-ico-gear" aria-hidden="true"></span><span>设置</span>
</button>
<button class="danger" data-action="delete" data-id="${t.id}">
<span class="ui-ico ui-ico-trash" aria-hidden="true"></span><span>删除</span>
</button>
</div>
${t.last_error ? `<p class="msg err is-visible"><span class="msg-icon" aria-hidden="true"></span><span class="msg-text">${escapeHtml(t.last_error)}</span></p>` : ""}
${renderLiveProgress(t)}
${renderTaskLog(t.last_log, t.id)}
</div>
</div>`;
}
function startKeepalive() {
if (state._keepAliveTimer) return;
state._keepAliveTimer = setInterval(() => {
if (document.hidden) return;
if ($("stageApp")?.hidden) return;
fetch("/api/auth/web-session", { credentials: "same-origin" }).catch(() => {});
}, 4 * 60 * 1000);
}
function stopKeepalive() {
if (state._keepAliveTimer) {
clearInterval(state._keepAliveTimer);
state._keepAliveTimer = null;
}
}
function tasksPollIntervalMs() {
const tasks = state.tasks || [];
const busy = tasks.some(
(t) => t.status === "running" || (t.live && t.live.phase === "indexing")
);
return busy ? 2000 : 5000;
}
function scheduleTasksPoll() {
stopPolling();
const tick = () => {
if (document.hidden) {
state.pollTimer = setTimeout(tick, 8000);
return;
}
if (!isOverlayBlockingPoll() && !state._tasksInflight) {
loadTasks().catch(() => {});
}
state.pollTimer = setTimeout(tick, tasksPollIntervalMs());
};
state.pollTimer = setTimeout(tick, tasksPollIntervalMs());
}
function startPolling() {
scheduleTasksPoll();
startKeepalive();
if (!state._resumeBound) {
state._resumeBound = true;
let lastResume = 0;
const resume = (ev) => {
if (document.hidden) return;
if (ev && ev.type === "pageshow" && ev.persisted) {
if ($("stageApp") && !$("stageApp").hidden && !state.pollTimer) {
startPolling();
}
return;
}
const now = Date.now();
if (now - lastResume < 2500) return;
lastResume = now;
if ($("stageApp") && !$("stageApp").hidden) {
if (!state.pollTimer) startPolling();
loadTasks().catch(() => {});
if (!state._tgLastOk || !state._tgLastOk.authorized) {
refreshTgState().catch(() => {});
}
}
};
document.addEventListener("visibilitychange", () => {
if (!document.hidden) resume({ type: "visibilitychange" });
});
window.addEventListener("pageshow", resume);
window.addEventListener("online", resume);
}
}
function stopPolling() {
if (state.pollTimer) {
clearTimeout(state.pollTimer);
clearInterval(state.pollTimer);
state.pollTimer = null;
}
}
function escapeHtml(s) {
return String(s ?? "")
.replaceAll("&", "&amp;")
.replaceAll("<", "&lt;")
.replaceAll(">", "&gt;")
.replaceAll('"', "&quot;");
}
